import hashlib

def h(text):
    return hashlib.sha256(text.encode()).hexdigest()[:8]

indexed = {"returns": h("30 days"), "shipping": h("2-5 days"), "gift-cards": h("no refunds")}
source = {"returns": "15 days", "shipping": "2-5 days", "warranty": "1 year"}

plan = {}
for doc, text in source.items():
    if doc not in indexed:
        plan[doc] = "insert"
    elif indexed[doc] != h(text):
        plan[doc] = "reindex"
    else:
        plan[doc] = "skip"
for doc in indexed.keys() - source.keys():
    plan[doc] = "delete"
for doc in sorted(plan):
    print(doc, plan[doc])

def answer(question, org_id):
    chunks = search(org_id, question, k=50)
    context = "\n".join(c.content for c in chunks)
    text = complete([{"role": "user", "content": f"{context}\n{question}\nCite your sources."}])
    return {"answer": text}
